const unauthenticatedFetch = globalThis.fetch;
function fetch(input: Parameters<typeof globalThis.fetch>[0], init: Parameters<typeof globalThis.fetch>[1] = {}) {
  const target = new URL(input instanceof Request ? input.url : String(input));
  if (target.pathname.startsWith('/api/') && target.pathname !== '/api/operator-auth' && (init?.method ?? 'GET') === 'GET') {
    const headers = new Headers(input instanceof Request ? input.headers : undefined);
    new Headers(init?.headers).forEach((value, key) => headers.set(key, value));
    if (!headers.has('Authorization')) headers.set('Authorization', 'Bearer test-token');
    return unauthenticatedFetch(input, {...init, headers});
  }
  return unauthenticatedFetch(input, init);
}

