function serviceWithJobs() { const control = service(), root = fs.mkdtempSync(path.join(os.tmpdir(), 'agent-control-web-jobs-')), actions = new ActionRegistry(); actions.register('test.run@1.0.0', async () => ({verification: ['ok']})); const catalog = new JobCatalog(actions.ids()); catalog.addJob({apiVersion: 'agent-control/v1', kind: 'Job', metadata: {id: 'web-job', name: 'Web Job', version: '1.0.0'}, spec: {priority: 'normal', concurrency: 'queue', parameters: {count: {type: 'integer', default: 2}, ratio: {type: 'number', default: 1.5}, enabled: {type: 'boolean', default: false}, label: {type: 'string', default: 'fixture'}, maximumOutputTokens: {type: 'integer', default: 32768}}, steps: [{id: 'run', action: 'test.run@1.0.0', requires: ['test'], approval: 'release', verification: ['ok']}]}}); const workers = new WorkerRegistry(); workers.register({id: 'worker', capabilities: ['test'], health: 'healthy', capacity: 1, active: 0, observedAt: now()}); const runtime = new JobRuntime(catalog, actions, workers, new RunLedger(path.join(root, 'ledger.json')), new ArtifactStore(path.join(root, 'artifacts')), new ResourceLockManager(path.join(root, 'locks.json'))); control.configureProjection({jobRuntime: runtime, resources: [{id: 'worker', name: 'Worker', platform: 'linux', transport: 'ssh', capabilities: ['test']}]}); return {control, runtime}; }
async function runningJobs(operatorToken: string | null = 'test-token') { const value = serviceWithJobs(), server = startWebDashboard(value.control, {host: '127.0.0.1', port: 0, operatorToken: operatorToken ?? undefined, assetsDir: path.resolve('assets/dashboard')}); await once(server, 'listening'); return {...value, server, base: `http://127.0.0.1:${(server.address() as AddressInfo).port}`}; }
