test('all control-plane API reads require authentication and route authority while assets and signed share routes remain separately governed', async t => {
  const control=service(),server=startWebDashboard(control,{host:'127.0.0.1',port:0,operatorToken:'test-token',operatorAuthorizer:(request,authority)=>authority==='control.read'&&request.headers['x-test-authority']==='read',assetsDir:path.resolve('assets/dashboard')});await once(server,'listening');t.after(()=>server.close());const base=`http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  assert.equal((await unauthenticatedFetch(base+'/api/status')).status,401);
  assert.equal((await unauthenticatedFetch(base+'/api/status',{headers:{Authorization:'Bearer wrong'}})).status,401);
  assert.equal((await unauthenticatedFetch(base+'/api/status',{headers:{Authorization:'Bearer test-token'}})).status,403);
  assert.equal((await unauthenticatedFetch(base+'/api/status',{headers:{Authorization:'Bearer test-token','X-Test-Authority':'read'}})).status,200);
  assert.equal((await unauthenticatedFetch(base+'/api/events')).status,401);
  assert.equal((await unauthenticatedFetch(base)).status,200);
});
