test('live execution-session API is authenticated, streams real redacted bytes and enforces WATCH/INTERVENE authority', async t => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'agent-control-web-execution-session-')); t.after(() => fs.rmSync(root, {recursive: true, force: true}));
  const control = service(), sessions = new ExecutionSessionRuntime(path.join(root, 'sessions')), writes: string[] = [], secret = `nvapi-web-${'s'.repeat(24)}`, id = 'session:web', incarnation = 'incarnation:web';
  sessions.create({id, incarnation, adapterId: 'fixture-pipe', scope: {runId: 'run:web', jobId: 'web-job', jobVersion: '1.0.0', stepId: 'run', actionId: 'test.run@1.0.0', workerId: 'worker', nodeId: 'controller', parcelId: 'parcel:web', crewRole: 'quality-inspector'}, command: 'bounded-test', cwd: '/workspace', pid: 201, capabilities: {observableOutput: true, interactiveInput: true, terminal: 'pipe', resize: false, signals: ['INTERRUPT'], suspendResume: false, persistent: false, reconnectable: false, remoteTransport: false, modes: {watch: true, intervene: true, takeControl: false}, limitations: ['fixture']}, runtimeCredentials: [secret], control: {prove: async () => ({sessionId: id, incarnation, state: 'RUNNING', pid: 201}), write: async value => { writes.push(value); }, signal: async () => {}}});
  control.configureProjection({executionSessions: sessions}); const server = startWebDashboard(control, {host: '127.0.0.1', port: 0, operatorToken: 'test-token', assetsDir: path.resolve('assets/dashboard')}); await once(server, 'listening'); t.after(() => server.close()); const base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`, headers = {'Content-Type': 'application/json', Authorization: 'Bearer test-token'};
  assert.equal((await unauthenticatedFetch(`${base}/api/execution-sessions`)).status, 401); assert.equal((await unauthenticatedFetch(`${base}/api/execution-sessions/${encodeURIComponent(id)}/stream`)).status, 401);
  const listed = await (await fetch(`${base}/api/execution-sessions`, {headers: {Authorization: 'Bearer test-token'}})).json(); assert.equal(listed[0].id, id); assert.equal(listed[0].scope.parcelId, 'parcel:web'); assert.equal('text' in listed[0], false);
  const watch = await (await fetch(`${base}/api/execution-sessions/${encodeURIComponent(id)}/attach`, {method: 'POST', headers, body: JSON.stringify({mode: 'WATCH'})})).json();
  const watchWrite = await fetch(`${base}/api/execution-sessions/${encodeURIComponent(id)}/input`, {method: 'POST', headers, body: JSON.stringify({attachmentId: watch.id, value: 'forbidden'})}); assert.equal(watchWrite.status, 403); assert.equal((await watchWrite.json()).error, 'execution_session_watch_read_only');
  const intervention = await (await fetch(`${base}/api/execution-sessions/${encodeURIComponent(id)}/attach`, {method: 'POST', headers, body: JSON.stringify({mode: 'INTERVENE'})})).json();
  const input = await fetch(`${base}/api/execution-sessions/${encodeURIComponent(id)}/input`, {method: 'POST', headers, body: JSON.stringify({attachmentId: intervention.id, value: 'approved\n'})}); assert.equal(input.status, 200); assert.deepEqual(writes, ['approved\n']);
  sessions.appendOutput(id, 'stdout', `real-before ${secret.slice(0, 8)}`); sessions.appendOutput(id, 'stdout', `${secret.slice(8)} real-after\n`); sessions.flushOutput(id);
  const abort = new AbortController(), response = await fetch(`${base}/api/execution-sessions/${encodeURIComponent(id)}/stream?after=0`, {headers: {Authorization: 'Bearer test-token'}, signal: abort.signal}); assert.equal(response.status, 200);
  const reader = response.body!.getReader(); let streamed = ''; for (let index = 0; index < 10 && !streamed.includes('real-after'); index++) streamed += new TextDecoder().decode((await reader.read()).value); abort.abort();
  assert.match(streamed, /event: output/); assert.match(streamed, /real-before/); assert.match(streamed, /real-after/); assert.equal(streamed.includes(secret), false); assert.match(streamed, /REDACTED/);
  const transcript = await (await fetch(`${base}/api/execution-sessions/${encodeURIComponent(id)}/transcript`, {headers: {Authorization: 'Bearer test-token'}})).json(); assert.match(transcript.content, /real-before/); assert.equal(transcript.content.includes(secret), false); assert.doesNotMatch(transcript.content, /approved/);
  const status = JSON.stringify(await (await fetch(`${base}/api/status`)).json()); assert.equal(status.includes('real-before'), false); assert.equal(status.includes(secret), false);
  for (const asset of ['dashboard-live-shell.css', 'dashboard-live-shell.js']) assert.equal((await fetch(`${base}/${asset}`)).status, 200);
});
