test('token routing projection is served and live telemetry is published through the SSE event stream', async t => { const {server, base, control} = await running(); t.after(() => server.close()); const routing = new TokenAwareBatonRuntime(); control.configureProjection({tokenBatonRouting: routing}); routing.subscribe(event => control.events.emit(event.type === 'telemetry' ? 'token.telemetry' : event.type === 'context.lifecycle' ? 'token.context_lifecycle' : 'token.governor_transition', {threadId: event.threadId, parcelId: event.parcelId}, undefined, 'test')); routing.observe({threadId: 'thread:one', parcelId: 'parcel:one', agentId: 'agent:one', providerId: 'openai', modelId: 'sol', elapsedMs: 1_000, cumulative: {inputTokens: 100, freshInputTokens: 70, cachedInputTokens: 30, outputTokens: 20, totalTokens: 120}, context: {tokens: 80, limitTokens: 100, authority: 'authoritative', source: 'provider'}}); routing.recordContextLifecycle('thread:one', {kind: 'COMPACTION', authority: 'authoritative', source: 'provider'}); const projection = await (await fetch(`${base}/api/token-routing`)).json(); assert.equal(projection.threads[0].latest.context.tokens, 80); assert.equal(projection.threads[0].latest.cumulative.freshInputTokens, 70); assert.equal(projection.threads[0].latest.cumulative.cachedInputTokens, 30); assert.equal(projection.threads[0].governor.state, 'PREPARE_BATON'); assert.equal(projection.contextLifecycle[0].kind, 'COMPACTION'); const abort = new AbortController(), response = await fetch(`${base}/api/events`, {headers: {'Last-Event-ID': '0'}, signal: abort.signal}), reader = response.body!.getReader(), first = await reader.read(), text = new TextDecoder().decode(first.value); abort.abort(); assert.match(text, /event: token\.telemetry/); assert.match(text, /event: token\.context_lifecycle/); assert.match(text, /"threadId":"thread:one"/); assert.match(text, /"tokens":80/); assert.match(text, /"cachedInputTokens":30/); });

