test('parcel context APIs expose asynchronous questions, steering, retrieval and first-class criteria through authenticated controls', async t => {
  const {server,base,workParcels,control}=await runningParcels('test-token');t.after(()=>server.close());const parcel=await workParcels.submit('preserve this exact goal','operator'),headers={'Content-Type':'application/json',Authorization:'Bearer test-token'};
  const asked=await fetch(`${base}/api/parcels/${parcel.id}/questions`,{method:'POST',headers,body:JSON.stringify({text:'Which format?',dependentStageIds:['inspect'],priority:'HIGH',consequence:'MEDIUM'})});assert.equal(asked.status,201);const waiting=await asked.json(),question=waiting.context.questions[0];assert.equal(waiting.status,'WAITING');assert.equal(waiting.context.active.originalGoal,'preserve this exact goal');assert.match(waiting.context.active.currentInterpretation,/interpreted:/);
  const answered=await fetch(`${base}/api/parcels/${parcel.id}/questions/${question.id}/answer`,{method:'POST',headers,body:JSON.stringify({answer:'JSON'})});assert.equal(answered.status,200);assert.equal((await answered.json()).context.questions[0].status,'ANSWERED');
  assert.equal((await fetch(`${base}/api/parcels/${parcel.id}/steering`,{method:'POST',headers,body:JSON.stringify({instruction:'Do not deploy',constraints:['read only']})})).status,200);
  const added=await fetch(`${base}/api/parcels/${parcel.id}/criteria`,{method:'POST',headers,body:JSON.stringify({kind:'CUSTOM',description:'Operator checks semantic result'})});assert.equal(added.status,201);const criterion=(await added.json()).criterion;
  const evaluated=await fetch(`${base}/api/parcels/${parcel.id}/criteria/${criterion.id}/evaluate`,{method:'POST',headers,body:JSON.stringify({status:'PASS',evidence:['operator:checked']})});assert.equal(evaluated.status,200);
  const retrieved=await fetch(`${base}/api/parcels/${parcel.id}/context/retrieve`,{method:'POST',headers,body:JSON.stringify({query:'Which format JSON'})});assert.equal(retrieved.status,200);assert.ok((await retrieved.json()).some((item:{type:string})=>item.type==='question.answered'));
  const invalid=await fetch(`${base}/api/parcels/${parcel.id}/criteria`,{method:'POST',headers,body:JSON.stringify({kind:'NOT_A_KIND',description:'invalid'})});assert.equal(invalid.status,400);assert.equal((await invalid.json()).error,'parcel_success_criterion_invalid');
  assert.ok(control.events.history().filter(event=>event.type==='work.parcel_changed').length>=5);
  const source=await(await fetch(`${base}/dashboard-enhancements.js`)).text();for(const marker of ['data-answer-question','data-steer-parcel','data-retrieve-parcel','data-add-criterion','data-evaluate-criterion'])assert.match(source,new RegExp(marker));
});

test('capability and model-intelligence APIs expose durable queue state and emit typed SSE-compatible events', async t => {
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'agent-control-web-intelligence-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const capabilities=new CapabilityIntelligenceStore(path.join(root,'capabilities.json'));registerAgentControlCoreCapabilities(capabilities,'2026-09-05T00:00:00Z');const intelligence=new ModelIntelligenceLedger(path.join(root,'models.json')),suite=loadFrozenQualificationSuite(path.resolve('config/qualification-suite-v1.json'));
  const registry=new ModelRegistry([{id:'provider',kind:'openai-compatible',baseUrl:'https://provider.example/v1',auth:{type:'none'}}],[{id:'candidate',provider:'provider',providerModel:'vendor/candidate',capabilities:['code.modify'],nodes:['controller'],qualification:{state:'UNTESTED'}}],{roles:{}},undefined,undefined,{},capabilities,intelligence),control=service();control.configureProjection({modelRegistry:registry,capabilityIntelligence:capabilities,modelIntelligence:intelligence,qualificationSuite:suite});const server=startWebDashboard(control,{host:'127.0.0.1',port:0,operatorToken:'test-token',assetsDir:path.resolve('assets/dashboard')});await once(server,'listening');t.after(()=>server.close());const base=`http://127.0.0.1:${(server.address() as AddressInfo).port}`,headers={'Content-Type':'application/json',Authorization:'Bearer test-token'};
  assert.equal((await(await fetch(`${base}/api/capability-intelligence`)).json()).totals.observations>0,true);assert.deepEqual((await(await fetch(`${base}/api/model-intelligence`)).json()).queue,[]);
  const discovered=await fetch(`${base}/api/capability-candidates`,{method:'POST',headers,body:JSON.stringify({id:'candidate-capability',title:'Provider continuation',source:'release notes',providerRuntime:'provider@1',claimedCapability:'context.lifecycle',whyItMatters:'less repetition',agentControlEquivalent:'context lifecycle',evidence:['Bearer abcdefghijklmnopqrstuvwxyz']})});assert.equal(discovered.status,201);assert.doesNotMatch(JSON.stringify(await discovered.json()),/abcdefghijklmnopqrstuvwxyz/);
  const invalidTransition=await fetch(`${base}/api/capability-candidates/candidate-capability/transition`,{method:'POST',headers,body:JSON.stringify({to:'ADOPTED',reason:'skip',finalDecision:'adopt'})});assert.equal(invalidTransition.status,409);assert.equal((await invalidTransition.json()).error,'capability_candidate_transition_invalid:DISCOVERED:ADOPTED');
  const queued=await fetch(`${base}/api/model-evaluations`,{method:'POST',headers,body:JSON.stringify({modelIds:['candidate'],reason:'operator qualification'})});assert.equal(queued.status,201);const batch=await queued.json();assert.equal(batch.status,'QUEUED');assert.equal(batch.suiteSha256,suite.sha256);assert.equal((await(await fetch(`${base}/api/model-intelligence`)).json()).queue[0].id,batch.id);
  assert.ok(control.events.history().some(event=>event.type==='capability.intelligence_changed'));assert.ok(control.events.history().some(event=>event.type==='model.intelligence_changed'));
  const html=await(await fetch(base)).text(),models=await(await fetch(`${base}/dashboard-models.js`)).text();assert.match(html,/Model intelligence/);assert.match(html,/Capability Watch/);assert.match(html,/Runtime Safety/);assert.match(models,/Frozen evaluation queue/);assert.match(models,/Regression warnings/);assert.match(models,/Best current coding model/);assert.match(models,/data-route-transition/);assert.match(models,/model-intelligence\/routes/);
});

